BEGIN;
DO $$BEGIN IF EXISTS(SELECT 1 FROM ai_construction_loan_entry_proposal) THEN RAISE EXCEPTION 'Cannot remove retained AI construction loan entry proposals' USING ERRCODE='55006';END IF;END$$;
REVOKE ALL ON FUNCTION refs_ai_construction_loan_entry_proposal_hash(uuid,uuid,uuid,text,uuid,text,text,text,jsonb,text),refs_propose_ai_construction_loan_entry(uuid,uuid,uuid,text,uuid,text,text,text,jsonb,text,text,text),refs_read_ai_construction_loan_entry_proposals(uuid,uuid,integer) FROM refs_app;
DROP FUNCTION refs_read_ai_construction_loan_entry_proposals(uuid,uuid,integer);DROP FUNCTION refs_propose_ai_construction_loan_entry(uuid,uuid,uuid,text,uuid,text,text,text,jsonb,text,text,text);DROP FUNCTION refs_ai_construction_loan_entry_proposal_hash(uuid,uuid,uuid,text,uuid,text,text,text,jsonb,text);DROP TABLE ai_construction_loan_entry_proposal;DELETE FROM permission_catalog WHERE permission_code='AI.LOAN.PROPOSE' AND NOT EXISTS(SELECT 1 FROM runtime_actor_grant WHERE permission='AI.LOAN.PROPOSE');COMMIT;
